        { id: "l102t5", type: "choice", q: "Какой символ нельзя использовать в имени файла в Windows?", answer: 1, options: ["Тире -", "Звёздочку *", "Подчёркивание _", "Цифру 7"], explain: "Символы \\ / : * ? \" < > | запрещены в именах файлов." }
